1	export interface Customer {
2	  yearsWithMHPCO: number;
3	}
4	
5	export interface Item {
6	  type: string;
7	  material?: string;
8	  enchantment?: number;
9	  cursed?: boolean;
10	}
11	
12	export interface QuoteStep {
13	  op: "quote";
14	  items: Item[];
15	}
16	
17	export interface Damage {
18	  itemType: string;
19	  amount: number;
20	}
21	
22	export interface ClaimStep {
23	  op: "claim";
24	  policy: number;
25	  incident: { cause: string; damages: Damage[] };
26	}
27	
28	export type Step = QuoteStep | ClaimStep;
29	
30	export interface Scenario {
31	  customer: Customer;
32	  steps: Step[];
33	}
34	
35	export type StepResult =
36	  | { premium: number }
37	  | { payout: number; remainingCap: number };
38	
39	export interface ScenarioResult {
40	  results: StepResult[];
41	}
42	
43	/**
44	 * Added at the very end of every premium, after all percentage modifiers, so
45	 * no surcharge or discount is ever computed on top of it.
46	 */
47	const PROCESSING_FEE = 5;
48	
49	/**
50	 * Rates are kept as exact numerator/denominator fractions rather than float
51	 * multipliers (10 / 100, never 1.1) so intermediate amounts stay exact and
52	 * only the final premium is rounded.
53	 */
54	const percent = (amount: number, rate: number): number => (amount * rate) / 100;
55	
56	const FIRST_INSURANCE_SURCHARGE_PERCENT = 10;
57	const CURSE_SURCHARGE_PERCENT = 50;
58	const HIGH_ENCHANTMENT_SURCHARGE_PERCENT = 30;
59	/**
60	 * Enchantment is read by two unrelated rules with different cut-offs: this one
61	 * charges a premium surcharge from 5 up, and REDUCED_REIMBURSEMENT_THRESHOLD
62	 * halves a claim from 8 up. Each threshold is named after the rule it gates so
63	 * the two cannot be mistaken for one shared notion of "highly enchanted".
64	 */
65	const ENCHANTMENT_SURCHARGE_THRESHOLD = 5;
66	const LOYALTY_DISCOUNT_PERCENT = 20;
67	const LOYALTY_THRESHOLD_YEARS = 2;
68	const FOLLOW_UP_DISCOUNT_PERCENT = 15;
69	
70	/**
71	 * Everything the pricing rules need to know about an item type lives here, so
72	 * that "what is a rune?" has a single answer. Components are the small parts
73	 * (runes, moonstones) that can be bought as a building block; main items
74	 * (swords, amulets, ...) never form a block.
75	 */
76	const ITEM_TYPES: Record<
77	  string,
78	  { unitPremium: number; insuranceValue: number; isComponent: boolean }
79	> = {
80	  sword: { unitPremium: 100, insuranceValue: 1000, isComponent: false },
81	  amulet: { unitPremium: 60, insuranceValue: 600, isComponent: false },
82	  staff: { unitPremium: 80, insuranceValue: 800, isComponent: false },
83	  potion: { unitPremium: 40, insuranceValue: 400, isComponent: false },
84	  rune: { unitPremium: 25, insuranceValue: 250, isComponent: true },
85	  moonstone: { unitPremium: 25, insuranceValue: 250, isComponent: true },
86	};
87	
88	/** A building block of 3 alike components is offered at this base premium. */
89	const COMPONENT_BLOCK_BASE_PREMIUM = 60;
90	const COMPONENT_BLOCK_SIZE = 3;
91	
92	/** Tallies how many items of each type a policy covers, e.g. [["rune", 3]]. */
93	const countByType = (items: Item[]): [string, number][] => {
94	  const counts = new Map<string, number>();
95	  for (const item of items) {
96	    counts.set(item.type, (counts.get(item.type) ?? 0) + 1);
97	  }
98	  return [...counts];
99	};
100	
101	/**
102	 * Prices every item of one type together, because exactly 3 alike components
103	 * form a block charged as one. "Alike" means the same type, and the block does
104	 * not repeat: 4 or 7 runes are each priced per item.
105	 */
106	const basePremiumForType = (type: string, count: number): number => {
107	  const { unitPremium, isComponent } = ITEM_TYPES[type];
108	  return isComponent && count === COMPONENT_BLOCK_SIZE
109	    ? COMPONENT_BLOCK_BASE_PREMIUM
110	    : count * unitPremium;
111	};
112	
113	const sumOfBasePremiums = (items: Item[]): number =>
114	  countByType(items).reduce(
115	    (sum, [type, count]) => sum + basePremiumForType(type, count),
116	    0,
117	  );
118	
119	/**
120	 * Item-specific modifiers: each applies to one item and is charged as a
121	 * percentage of THAT item's unit premium, never of the policy total.
122	 * They stack — an item matching several rules is charged for each.
123	 *
124	 * Unit premium, not the item's share of the policy base: the two differ only
125	 * for components inside a block of 3 (billed 60 G for three 25 G runes), and
126	 * no test pins down a surcharged component yet. Revisit when one does.
127	 */
128	const ITEM_MODIFIERS: { appliesTo: (item: Item) => boolean; rate: number }[] = [
129	  { appliesTo: (item) => item.cursed === true, rate: CURSE_SURCHARGE_PERCENT },
130	  {
131	    appliesTo: (item) =>
132	      (item.enchantment ?? 0) >= ENCHANTMENT_SURCHARGE_THRESHOLD,
133	    rate: HIGH_ENCHANTMENT_SURCHARGE_PERCENT,
134	  },
135	];
136	
137	const surchargeForItem = (item: Item): number =>
138	  ITEM_MODIFIERS.filter(({ appliesTo }) => appliesTo(item)).reduce(
139	    (sum, { rate }) => sum + percent(ITEM_TYPES[item.type].unitPremium, rate),
140	    0,
141	  );
142	
143	const sumOfItemSurcharges = (items: Item[]): number =>
144	  items.reduce((sum, item) => sum + surchargeForItem(item), 0);
145	
146	/**
147	 * Policy-wide modifiers: each is charged as a percentage of the POLICY BASE
148	 * premium (the sum of item base premiums, before any item surcharge), so no
149	 * modifier is ever computed on top of another. Discounts carry a negative rate.
150	 */
151	interface PolicyContext {
152	  customer: Customer;
153	  /** Quotes already issued to this customer earlier in the scenario. */
154	  previousContracts: number;
155	}
156	
157	const POLICY_MODIFIERS: {
158	  appliesTo: (context: PolicyContext) => boolean;
159	  rate: number;
160	}[] = [
161	  // Always applies: every item in a quote is treated as a first insurance,
162	  // regardless of how long the customer has been with the MHPCO.
163	  { appliesTo: () => true, rate: FIRST_INSURANCE_SURCHARGE_PERCENT },
164	  {
165	    // Negative rate: a discount is just a surcharge pointing the other way, so
166	    // it needs no separate code path and cannot stack onto another modifier.
167	    appliesTo: ({ customer }) =>
168	      customer.yearsWithMHPCO >= LOYALTY_THRESHOLD_YEARS,
169	    rate: -LOYALTY_DISCOUNT_PERCENT,
170	  },
171	  {
172	    appliesTo: ({ previousContracts }) => previousContracts >= 1,
173	    rate: -FOLLOW_UP_DISCOUNT_PERCENT,
174	  },
175	];
176	
177	const sumOfPolicyAdjustments = (
178	  context: PolicyContext,
179	  policyBasePremium: number,
180	): number =>
181	  POLICY_MODIFIERS.filter(({ appliesTo }) => appliesTo(context)).reduce(
182	    (sum, { rate }) => sum + percent(policyBasePremium, rate),
183	    0,
184	  );
185	
186	const premiumFor = (context: PolicyContext, items: Item[]): number => {
187	  const policyBasePremium = sumOfBasePremiums(items);
188	  return Math.ceil(
189	    policyBasePremium +
190	      sumOfItemSurcharges(items) +
191	      sumOfPolicyAdjustments(context, policyBasePremium) +
192	      PROCESSING_FEE,
193	  );
194	};
195	
196	/** A policy created by a quote step, tracked so later claims can draw on it. */
197	interface Policy {
198	  items: Item[];
199	  remainingCap: number;
200	}
201	
202	const DEDUCTIBLE_PER_DAMAGE = 100;
203	const CAP_MULTIPLE_OF_INSURANCE_SUM = 2;
204	
205	const insuranceSumOf = (items: Item[]): number =>
206	  items.reduce((sum, item) => sum + ITEM_TYPES[item.type].insuranceValue, 0);
207	
208	const REDUCED_REIMBURSEMENT_THRESHOLD = 8;
209	const REDUCED_REIMBURSEMENT_PERCENT = 50;
210	
211	/** Reimbursed in full when no clause below claims the item. */
212	const FULL_REIMBURSEMENT_PERCENT = 100;
213	const DRAGON_MATERIAL = "dragon";
214	
215	/**
216	 * Clauses that change how much of a damage is reimbursed. Ordered by
217	 * precedence: the FIRST match wins and the rest are skipped, because clauses
218	 * overlap (a highly enchanted dragon-material item matches more than one) and
219	 * they are alternatives, not stacking modifiers like ITEM_MODIFIERS.
220	 */
221	const REIMBURSEMENT_CLAUSES: {
222	  appliesTo: (item: Item) => boolean;
223	  rate: number;
224	}[] = [
225	  {
226	    appliesTo: (item) =>
227	      (item.enchantment ?? 0) >= REDUCED_REIMBURSEMENT_THRESHOLD,
228	    rate: REDUCED_REIMBURSEMENT_PERCENT,
229	  },
230	  // Listed after the clause above so that a highly enchanted dragon item is
231	  // still reimbursed at 50 %. This entry yields exactly what the no-clause
232	  // default yields, so removing it would not change any current result — it is
233	  // here because the spec states dragon material as a rule, and because the
234	  // ordering is what makes the 50 % rule win.
235	  {
236	    appliesTo: (item) => item.material === DRAGON_MATERIAL,
237	    rate: FULL_REIMBURSEMENT_PERCENT,
238	  },
239	];
240	
241	const reimbursementRateFor = (item: Item): number =>
242	  REIMBURSEMENT_CLAUSES.find(({ appliesTo }) => appliesTo(item))?.rate ??
243	  FULL_REIMBURSEMENT_PERCENT;
244	
245	/**
246	 * The clause is applied to the damage first; the deductible comes off whatever
247	 * the clause leaves.
248	 */
249	const payoutForDamage = (damage: Damage, insuredItems: Item[]): number => {
250	  // Unguarded: no test yet describes a damage naming an item the policy does
251	  // not cover. The "claim references an item not covered" test will force this
252	  // honest.
253	  const damagedItem = insuredItems.find(
254	    (item) => item.type === damage.itemType,
255	  ) as Item;
256	  return (
257	    percent(damage.amount, reimbursementRateFor(damagedItem)) -
258	    DEDUCTIBLE_PER_DAMAGE
259	  );
260	};
261	
262	/**
263	 * The contract a quote step issues: what it covers, and how much of its cap is
264	 * still available to later claims.
265	 */
266	const policyFor = (items: Item[]): Policy => ({
267	  items,
268	  remainingCap: CAP_MULTIPLE_OF_INSURANCE_SUM * insuranceSumOf(items),
269	});
270	
271	/**
272	 * What an incident is worth against a policy, as a pure calculation: each
273	 * damage is settled on its own (own clause, own deductible) and the results are
274	 * added up. Drawing this down from the policy's cap is the caller's job.
275	 */
276	const payoutForIncident = (
277	  incident: ClaimStep["incident"],
278	  insuredItems: Item[],
279	): number =>
280	  incident.damages.reduce(
281	    (sum, damage) => sum + payoutForDamage(damage, insuredItems),
282	    0,
283	  );
284	
285	/**
286	 * Steps are executed in order because a step's result can depend on the ones
287	 * before it: the count of contracts already issued decides the follow-up
288	 * discount, and the policies a quote registers are what later claims draw on.
289	 */
290	export const runScenario = (scenario: Scenario): ScenarioResult => {
291	  let previousContracts = 0;
292	  const policies = new Map<number, Policy>();
293	
294	  const results = scenario.steps.map((step, index): StepResult => {
295	    if (step.op === "claim") {
296	      // Unguarded: no test yet describes a claim naming a policy that was never
297	      // quoted. The "claim references an item/policy not in the policy" test
298	      // will force this honest.
299	      const policy = policies.get(step.policy) as Policy;
300	      // The cap is a ceiling, not just a running total: once it is exhausted a
301	      // claim is paid only what is left of it.
302	      const payout = Math.min(
303	        payoutForIncident(step.incident, policy.items),
304	        policy.remainingCap,
305	      );
306	      // The one mutation in the module, kept here beside the scenario's other
307	      // cross-step state: what this claim consumes has to be visible to every
308	      // later claim on the same policy.
309	      policy.remainingCap -= payout;
310	      return { payout, remainingCap: policy.remainingCap };
311	    }
312	
313	    const premium = premiumFor(
314	      { customer: scenario.customer, previousContracts },
315	      step.items,
316	    );
317	    policies.set(index, policyFor(step.items));
318	    // Counted after pricing, so a quote never discounts itself, and only for
319	    // quotes, because a claim does not issue a contract.
320	    previousContracts += 1;
321	    return { premium };
322	  });
323	  return { results };
324	};
